#pragma once
#include <cstddef>
#include <cstdint>
#include <initializer_list>
#include "greeneye.h"

// Game functions found by signature when the mod starts, so a patch that only moves code needs no update.
// Source code names a function by its address in the reference build (game build 1287369); those numbers
// are keys and never change. portal_natives_table.h is generated by tools/patchcheck/gensig.py.
namespace portal::natives {
// Finds everything in one pass over the exe. Call once per generation, on the game client only.
void Resolve(const GreeneyeHost* host);
// The live address of a reference-build address; null when it wasn't found.
uint8_t* At(uint32_t referenceRva);
bool Has(std::initializer_list<uint32_t> referenceRvas);
// Every native function and every layout guard matched, and no crash on this build: the in-frame
// renderer and the pictures may run.
bool RenderReady();
// The crash guard: on a build this version wasn't made for, a session that dies before it has played
// for a while keeps the native features off on that build at the next start.
bool Tripped();
void NoteStablePlay();
}
